  const [decision, setDecision] = useState<Decision | null>(null), [reason, setReason] = useState<Reason>("mass"), [notice, setNotice] = useState("");
  const [audio, setAudio] = useState(false), [mobileTab, setMobileTab] = useState<"specimen" | "passport">("specimen");
  const dialog = useRef<HTMLDialogElement>(null), heading = useRef<HTMLHeadingElement>(null), file = useRef<HTMLInputElement>(null);
  const item = s && currentCase(s), currentId = item?.id;
