  useEffect(() => { setTool("inspect"); setDecision(null); setReason("mass"); setMobileTab("specimen"); }, [currentId, game.slot]);
  useEffect(() => { if (panel) dialog.current?.showModal(); else dialog.current?.close(); }, [panel]);
  useEffect(() => { if (s?.phase !== "desk") heading.current?.focus({ preventScroll: true }); }, [s?.phase]);
