    catch (error) {
      const code = error instanceof Error ? error.message : "";
      const messages: Record<string, string> = { no_time: t("В этой смене не осталось времени на исследование.", "There is not enough work time for that examination."), no_budget: t("Не хватает денег отделения. Дождитесь выплаты после смены.", "Insufficient office funds. Wait for the shift payment."), hold_unavailable: t("Отсрочка недоступна: проверьте места и срок приёма.", "Deferral unavailable: check capacity and the admissions deadline."), guarantee_unavailable: t("Поручительство уже использовано или ещё не выдано.", "Your guarantee has been used or is not yet available."), missing_proof: t("Выберите два документа об одном нарушении и соответствующий им вывод.", "Choose two exhibits about the same violation and the conclusion they support."), ending_locked: t("Для этого решения пока не выполнены условия.", "The conditions for this decision are not yet met.") };
      setNotice(messages[code] ?? t("Это действие сейчас недоступно. Проверьте текущий этап дела.", "That action is not available now. Check the current stage of the file."));
    }
