    if (r.correct) return r.decision === "guarantee" ? t("Несоответствие свидетельства открыто указано. Поручительство оформлено обоснованно.", "The certificate issue is explicitly recorded. The guarantee is justified.") : t("Проверка завершена: ваше решение подтверждается образцом и документами.", "Review complete: the specimen and documents support your decision.");
